PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  name          TEXT NOT NULL,
  email         TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  password_salt TEXT NOT NULL,
  role          TEXT NOT NULL DEFAULT 'user',   -- 'user' | 'admin'
  avatar_key    TEXT,                            -- R2 object key
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE sessions (
  token      TEXT PRIMARY KEY,
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE store_items(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,name TEXT NOT NULL,description TEXT,subject TEXT,grade TEXT,file_type TEXT,size_bytes INTEGER DEFAULT 0,price_tzs INTEGER DEFAULT 0,rating_avg REAL DEFAULT 0,rating_count INTEGER DEFAULT 0,downloads INTEGER DEFAULT 0,status TEXT DEFAULT 'pending',featured INTEGER DEFAULT 0,target_app TEXT,seller_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP, license TEXT DEFAULT 'single', stock INTEGER);
CREATE TABLE store_versions(id INTEGER PRIMARY KEY AUTOINCREMENT,item_id INTEGER,version INTEGER,r2_key TEXT,sha256 TEXT,size_bytes INTEGER,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE store_library(user_id INTEGER,item_id INTEGER,version INTEGER,acquired_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,item_id));
CREATE TABLE store_wishlist(user_id INTEGER,item_id INTEGER,PRIMARY KEY(user_id,item_id));
CREATE TABLE store_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,receipt_no TEXT UNIQUE,user_id INTEGER,total_tzs INTEGER,discount_tzs INTEGER DEFAULT 0,coupon TEXT,method TEXT,phone TEXT,status TEXT DEFAULT 'pending',provider_ref TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP, delivery TEXT, pickup TEXT, gift_email TEXT, ship TEXT DEFAULT 'received', gift_msg TEXT);
CREATE TABLE store_order_items(order_id INTEGER,item_id INTEGER,price_tzs INTEGER,seats INTEGER DEFAULT 1);
CREATE TABLE store_reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,item_id INTEGER,user_id INTEGER,stars INTEGER,body TEXT,verified INTEGER DEFAULT 0,reports INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP, reply TEXT, reply_at TEXT);
CREATE TABLE store_coupons(code TEXT PRIMARY KEY,percent INTEGER,max_uses INTEGER,used INTEGER DEFAULT 0,expires_at TEXT);
CREATE TABLE store_bundles(id INTEGER PRIMARY KEY AUTOINCREMENT,owner_id INTEGER,institution_id INTEGER,item_id INTEGER,seats INTEGER);
CREATE TABLE store_bundle_seats(bundle_id INTEGER,user_id INTEGER,PRIMARY KEY(bundle_id,user_id));
CREATE TABLE store_devices(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,name TEXT,token_hash TEXT,last_sync TEXT);
CREATE TABLE store_device_files(device_id INTEGER,item_id INTEGER,version INTEGER,PRIMARY KEY(device_id,item_id));
CREATE TABLE store_sellers(user_id INTEGER PRIMARY KEY,share_percent INTEGER DEFAULT 70,approved INTEGER DEFAULT 0, verified INTEGER DEFAULT 0);
CREATE TABLE store_referrals(code TEXT PRIMARY KEY,owner_id INTEGER,uses INTEGER DEFAULT 0);
CREATE TABLE store_payouts(id INTEGER PRIMARY KEY AUTOINCREMENT,seller_id INTEGER,amount_tzs INTEGER,method TEXT,phone TEXT,status TEXT DEFAULT 'requested',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE store_previews(item_id INTEGER,n INTEGER,r2_key TEXT,PRIMARY KEY(item_id,n));
CREATE TABLE store_collections(id INTEGER PRIMARY KEY,name TEXT,percent INTEGER,item_ids TEXT);
CREATE TABLE store_subscriptions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,item_id INTEGER,expires_at TEXT,seats INTEGER DEFAULT 1);
CREATE TABLE store_notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,kind TEXT,title TEXT,body TEXT,link TEXT,read INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE store_refunds(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER UNIQUE,user_id INTEGER,reason TEXT,status TEXT DEFAULT 'requested',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE store_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT,detail TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE store_review_votes(review_id INTEGER,user_id INTEGER,PRIMARY KEY(review_id,user_id));
CREATE TABLE store_watch(user_id INTEGER,item_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,item_id));
CREATE TABLE store_classes(id INTEGER PRIMARY KEY AUTOINCREMENT,teacher_id INTEGER NOT NULL,name TEXT NOT NULL,code TEXT UNIQUE NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE store_class_members(class_id INTEGER,user_id INTEGER,joined_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(class_id,user_id));
CREATE TABLE store_class_items(class_id INTEGER,item_id INTEGER,pushed_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(class_id,item_id));
CREATE TABLE store_lists(code TEXT PRIMARY KEY,user_id INTEGER UNIQUE,title TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE store_points_log(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,reason TEXT,ref TEXT,pts INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,reason,ref));
CREATE TABLE store_points_state(user_id INTEGER PRIMARY KEY,last_day TEXT,streak INTEGER DEFAULT 0);
CREATE TABLE store_item_views(item_id INTEGER,day TEXT,n INTEGER DEFAULT 0,PRIMARY KEY(item_id,day));
CREATE TABLE store_search_hits(item_id INTEGER,q TEXT,n INTEGER DEFAULT 0,PRIMARY KEY(item_id,q));
DELETE FROM sqlite_sequence;
